import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.CXroN2RO.js";const d="/study/images/browser/audio-spatial-coordinates.svg",n="/study/images/browser/audio-spatial-gains.svg",b=JSON.parse('{"title":"Web Audioの音の定位と距離減衰","description":"","frontmatter":{"title":"Web Audioの音の定位と距離減衰","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"音源と聞き手の相対位置から方位角と距離を求め、左右の振幅と距離による音量の変化を計算する。","aliases":["Web Audio API","PannerNode","AudioListener","StereoPannerNode","音の定位","立体音響","距離減衰","方位角","equalpower","等電力パンニング","HRTF","HRIR"],"verification":"W3C Web Audio APIのPannerNodeと空間化の計算手順に照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-spatial-panning.md","filePath":"browser/audio-spatial-panning.md"}'),i={name:"browser/audio-spatial-panning.md"};function s(c,e,l,p,u,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="web-audioの音の定位と距離減衰" tabindex="-1">Web Audioの音の定位と距離減衰 <a class="header-anchor" href="#web-audioの音の定位と距離減衰" aria-label="Permalink to &quot;Web Audioの音の定位と距離減衰&quot;">​</a></h1><p>ゲームで右前方の敵が足音を立てたとき、音を右寄りにし、遠くにいれば小さくすると、姿が見えなくても方向と距離の手がかりになります。Web Audioの <code>PannerNode</code> は、聞き手に対する音源の位置から左右2チャンネルの出力を作ります。ここではモノラルの音源に、左右の振幅を決める<strong>等電力パンニング</strong>と、離れるほど音を小さくする<strong>距離減衰</strong>を適用します。<a href="https://www.w3.org/TR/webaudio/#PannerNode" target="_blank" rel="noreferrer">W3C Web Audio APIのPannerNode</a></p><h2 id="聞き手から見た方向と距離を求める" tabindex="-1">聞き手から見た方向と距離を求める <a class="header-anchor" href="#聞き手から見た方向と距離を求める" aria-label="Permalink to &quot;聞き手から見た方向と距離を求める&quot;">​</a></h2><p>音源の位置は <code>PannerNode</code> の <code>positionX</code>、<code>positionY</code>、<code>positionZ</code> で指定します。聞き手を表す <code>AudioListener</code> は、位置と向きを持ちます。初期状態では聞き手が原点にいて、前が <strong>−Z</strong>、上が <strong>+Y</strong>、右が <strong>+X</strong> です。聞き手が回転すると、同じ位置の音源でも聞き手から見た方向は変わります。<a href="https://www.w3.org/TR/webaudio/#AudioListener" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioListener</a></p><p>音源の位置から聞き手の位置を引くと、聞き手から音源へ向かうベクトルが得られます。その長さ <code>d</code> が距離です。ベクトルを聞き手の水平面に投影し、前から測った角度を<strong>方位角</strong>と呼びます。前が0°、右が+90°、左が−90°です。同じ方位角のまま音源を遠ざけると、角度を変えずに距離だけを変えられます。<a href="https://www.w3.org/TR/webaudio/#azimuth-elevation" target="_blank" rel="noreferrer">W3C Web Audio APIの方位角と仰角</a></p><figure class="study-figure"><img src="'+d+`" alt="聞き手を上から見た図。前はマイナスZ、右はプラスX。右前の音源への線の長さが距離d、前からその線までの角度が方位角a。" width="760" height="416" loading="lazy"><figcaption>聞き手と音源が同じ高さにある例です。上方向の+Yは画面の手前を向きます。<a href="/study/images/browser/audio-spatial-coordinates.svg" target="_blank" rel="noopener noreferrer">座標と方位角の図を拡大</a></figcaption></figure><p>聞き手を原点に固定し、音源を同じ高さに置くと、距離 <code>d</code> と方位角 <code>a</code> から音源の座標を求められます。三角関数には度で表した <code>a</code> をラジアンに直して渡します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = d × sin(a × π / 180)</span></span>
<span class="line"><span>y = 0</span></span>
<span class="line"><span>z = −d × cos(a × π / 180)</span></span></code></pre></div><h2 id="左右の振幅を等電力で分ける" tabindex="-1">左右の振幅を等電力で分ける <a class="header-anchor" href="#左右の振幅を等電力で分ける" aria-label="Permalink to &quot;左右の振幅を等電力で分ける&quot;">​</a></h2><p><code>panningModel</code> を <code>&quot;equalpower&quot;</code> にし、モノラルの入力を与えます。前半分の方位角 <code>a</code>（−90°〜+90°）から <code>θ = (a + 90) × π / 360</code> を求めると、距離減衰を掛ける前の左右の振幅比は <code>cos(θ)</code> と <code>sin(θ)</code> です。正面では左右とも約0.707、真横では音源がある側が1で反対側が0になります。左右の振幅比の二乗を足すと、どの角度でも1です。ここでの「等電力」はこの二乗和を指します。聞こえ方は再生機器や周囲の環境にも左右されます。<a href="https://www.w3.org/TR/webaudio/#Spatialization-equal-power-panning" target="_blank" rel="noreferrer">W3C Web Audio APIの等電力パンニング</a></p><h2 id="距離のゲインを両方に掛ける" tabindex="-1">距離のゲインを両方に掛ける <a class="header-anchor" href="#距離のゲインを両方に掛ける" aria-label="Permalink to &quot;距離のゲインを両方に掛ける&quot;">​</a></h2><p><code>distanceModel</code> を <code>&quot;inverse&quot;</code>、基準距離 <code>refDistance</code> と減衰の強さ <code>rolloffFactor</code> をともに1とします。音源はどの向きにも同じ強さで音を出す設定です。距離が1以下ならゲインは1です。1より遠くでは <code>g = 1 / d</code> になり、距離2で0.5、距離4で0.25になります。この <code>g</code> を左右の振幅比に同じように掛けるため、向きが同じなら左右の比を保ったまま両方が小さくなります。この設定では距離が1以上の範囲で2倍になるたび、振幅が半分になり、約6.02 dB下がります。<a href="https://www.w3.org/TR/webaudio/#enumdef-distancemodeltype" target="_blank" rel="noreferrer">W3C Web Audio APIの距離モデル</a></p><figure class="study-figure"><img src="`+n+'" alt="左の図では方位角に応じて左の振幅比が1から0に下がり、右が0から1に上がる。正面では両方とも約0.707。右の図では距離1まではゲイン1で、距離2では0.5、距離4では0.25、距離8では0.125。" width="760" height="412" loading="lazy"><figcaption>方位角から左右への配分を決め、距離に応じた同じゲインを両方に掛けます。<a href="/study/images/browser/audio-spatial-gains.svg" target="_blank" rel="noopener noreferrer">振幅比と距離ゲインの図を拡大</a></figcaption></figure><p>例えば右前45°、距離2では、距離ゲインを掛けた出力の振幅比は左が約0.191、右が約0.462です。左右それぞれの出力の実効値（RMS）を入力の実効値で割って <code>L</code>、<code>R</code> とすると、<code>√(L² + R²)</code> は約0.5です。この指標で、左右への振り分けと両方に共通する距離減衰を分けて確認できます。</p><h2 id="左右の配分から方向ごとの耳への届き方へ" tabindex="-1">左右の配分から方向ごとの耳への届き方へ <a class="header-anchor" href="#左右の配分から方向ごとの耳への届き方へ" aria-label="Permalink to &quot;左右の配分から方向ごとの耳への届き方へ&quot;">​</a></h2><p><code>equalpower</code> は後方の方位角を前方側に折り返して計算し、仰角を使いません。例えば同じ距離で正面と真後ろに置いた音源は、左右への配分が同じです。方向によって左右の耳に音が届く時刻や周波数ごとの強さが変わる効果も加えるなら、<code>panningModel</code> に <code>&quot;HRTF&quot;</code> を使えます。HRTFは頭や耳の形による方向ごとの伝わり方を表し、実装ではその時間領域の応答であるHRIRを左右の耳ごとに畳み込みます。<a href="https://www.w3.org/TR/webaudio/#Spatialization-hrtf-panning" target="_blank" rel="noreferrer">W3C Web Audio APIのHRTFパンニング</a>、<a href="/study/browser/audio-convolution-reverb.html">Web Audioの畳み込みリバーブ</a></p><p>画面のUI効果音のように、空間上の位置を与えず左右の配分だけを直接指定したい場合は、<code>StereoPannerNode</code> の <code>pan</code> を使えます。<code>pan</code> の範囲は−1〜1で、0が中央です。<a href="https://www.w3.org/TR/webaudio/#StereoPannerNode" target="_blank" rel="noreferrer">W3C Web Audio APIのStereoPannerNode</a></p><h2 id="ゲームの座標と結び付ける" tabindex="-1">ゲームの座標と結び付ける <a class="header-anchor" href="#ゲームの座標と結び付ける" aria-label="Permalink to &quot;ゲームの座標と結び付ける&quot;">​</a></h2><p>プレイヤーが見ている方向に音を合わせるなら、カメラの位置、前、上を聞き手に設定し、足音などの発生位置を音源に設定します。ゲーム側の前方向や座標の単位が異なる場合は、向きと位置を同じ基準で変換し、想定する距離で音量が落ちるように基準距離を調整します。壁越しの音を小さくしたりこもらせたりする場合は、ゲーム側で遮蔽を判定し、別のゲインやフィルターに反映します。<a href="https://www.w3.org/TR/webaudio/#Spatialization" target="_blank" rel="noreferrer">W3C Web Audio APIの空間化とパンニング</a></p><p>実践では同じモノラル音を <code>OfflineAudioContext</code> の <code>PannerNode</code> に通し、左右の出力の実効値を測ります。距離を固定して角度を変え、次に角度を固定して距離を変えると、左右への配分と距離減衰を一つずつ確かめられます。<a href="/study/practice/browser/audio-spatial-observation.html">音の定位と距離減衰の実践</a></p>',20)])])}const w=o(i,[["render",s]]);export{b as __pageData,w as default};
